<script id="pio-karta-telefon-js">
/* Карта на телефону: један прст помера страницу, два прста или стрелице померају и увећавају карту (14. 11. 2026) */
(function(){
  if(!(window.matchMedia&&window.matchMedia('(max-width:760px)').matches)) return;
  var n=0, t=setInterval(function(){
    var m=window.__rajacLeafletHomeMap; if(++n>240){clearInterval(t);return;}
    if(!m) return; clearInterval(t);
    try{ m.dragging.disable(); }catch(e){}
    try{ if(m.touchZoom) m.touchZoom.enable(); }catch(e){}
    var c=m.getContainer(), h=document.createElement('div'), tm;
    h.textContent='Карту померајте са два прста или стрелицама';
    h.setAttribute('aria-hidden','true');
    h.style.cssText='position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:900;max-width:80%;padding:10px 14px;border-radius:12px;background:rgba(12,20,13,.82);color:#fff;font:600 13px/1.35 system-ui,-apple-system,"Segoe UI",sans-serif;text-align:center;pointer-events:none;opacity:0;transition:opacity .25s';
    c.appendChild(h);
    c.addEventListener('touchstart',function(e){
      if(e.touches&&e.touches.length===1&&!(e.target.closest&&e.target.closest('.leaflet-control'))){ h.style.opacity='1'; clearTimeout(tm); tm=setTimeout(function(){ h.style.opacity='0'; },1400); }
      else h.style.opacity='0';
    },{passive:true});
  },500);
})();
</script>
